parameters.inputSchema:
={
  "type": "object",
  "properties": {
    "reasoning": {
      "type": "object",
      "description": "Internal scratchpad. Complete this BEFORE filling any other field.",
      "properties": {
        "core_skills_found": {
          "type": "string",
          "description": "For each core skill: FOUND/NOT FOUND + one direct quote max. Max 3 sentences total. End with exactly: 'MATCH COUNT: N' where N is the integer you will use for core_skills_match_count."
        },
        "secondary_tools_found": {
          "type": "string",
          "description": "List only FOUND tools with one quote each. Skip NOT FOUND. Max 4 sentences total."
        },
        "skill_gaps_required": {
          "type": "string",
          "description": "List each known skill gap. For each: hard requirement / nice-to-have / not mentioned."
        },
        "muss_kriterien_met": {
          "type": "string",
          "description": "For each criterion: YES/NO + max 8 words of evidence. One line per criterion."
        },
        "strategic_checklist": {
          "type": "string",
          "description": "Three lines only: one per criterion. Format: (n) criterion name: YES/NO +X. Total: X."
        },
        "project_evidence": {
          "type": "string",
          "description": "Max 3 projects. Format: [Name]: [metric] — [relevance]. One line per project."
        }
      },
      "required": ["core_skills_found", "secondary_tools_found", "skill_gaps_required", "muss_kriterien_met", "strategic_checklist", "project_evidence"]
    },
    "company":           { "type": "string" },
    "role_title":        { "type": "string" },
    "scoring_inputs": {
      "type": "object",
      "description": "Semantic judgments only. The Code Node computes all scores from these.",
      "properties": {
        "core_skills_match_count": {
          "type": "integer",
          "description": "Number of candidate's core skills explicitly required by the posting. Count only exact or direct matches. Must equal the MATCH COUNT stated at the end of reasoning.core_skills_found."
        },
        "secondary_tools_match_count": {
          "type": "integer",
          "description": "Number of candidate's secondary tools found in the posting (required or nice-to-have)."
        },
        "skill_gaps_classification": {
          "type": "string",
          "enum": ["hard_requirement", "nice_to_have", "not_required"],
          "description": "Classify the most penalizing known skill gap present in the posting. TIEBREAKER: if the same skill appears as both a responsibility and a nice-to-have, classify as hard_requirement."
        },
        "muss_kriterien_met": {
          "type": "integer",
          "description": "Number of Muss-Kriterien the candidate clearly meets."
        },
        "muss_kriterien_total": {
          "type": "integer",
          "description": "Total number of Muss-Kriterien identified in the posting."
        },
        "format_match": {
          "type": "string",
          "enum": ["full", "none"],
          "description": "Does the posting match the candidate's target work format? 'full' if offered fully or as one option among others. 'none' if not offered at all."
        },
        "role_type_category": {
          "type": "string",
          "enum" : {{ JSON.stringify(Object.keys($('Start').first().json.role_type_scores)) }},
          "description": "Select the ONE category that best describes this posting's responsibilities. Must be one of the values listed."
        },
        "location_classification": {
          "type": "string",
          "enum": [
            "remote",
            "hybrid_commutable_90",
            "hybrid_commutable_150",
            "onsite_commutable_90",
            "onsite_commutable_150",
            "onsite_not_commutable"
          ],
          "description": "Classify the work arrangement and distance from candidate base."
        },
        "strategic_brand": {
          "type": "boolean",
          "description": "True if strong employer brand or exceptional learning environment."
        },
        "strategic_ai": {
          "type": "boolean",
          "description": "True if the role involves AI / RAG / IDP / vector-adjacent work as a real responsibility."
        },
        "strategic_gaps_exposure": {
          "type": "boolean",
          "description": "True if the posting explicitly requires or teaches any of the candidate's known skill gaps."
        }
      },
      "required": [
        "core_skills_match_count",
        "secondary_tools_match_count",
        "skill_gaps_classification",
        "muss_kriterien_met",
        "muss_kriterien_total",
        "format_match",
        "role_type_category",
        "location_classification",
        "strategic_brand",
        "strategic_ai",
        "strategic_gaps_exposure"
      ]
    },
    "muss_kriterien":    { "type": "array", "items": { "type": "string" } },
    "wunsch_kriterien": {
      "type": "array",
      "items": { "type": "string" },
      "description": "Preferred or nice-to-have tools, skills, or qualifications from the posting. Max 6 short strings, e.g. ['GitHub Copilot', 'VS Code', 'PowerShell']. Include anything described as 'a plus', 'preferred', 'nice to have', 'von Vorteil', or 'wünschenswert'."
    },
    "gaps":              { "type": "array", "items": { "type": "string" } },
    "highlights":        { "type": "array", "items": { "type": "string" } },
    "company_one_liner": { "type": "string" },
    "anschreiben_hook":  { "type": "string" },
    "contact_person": {
      "type": ["string", "null"]
    },
    "location_type":     {
      "type": "string",
      "enum": ["remote","hybrid_nrw","hybrid_frankfurt","onsite_nrw","onsite_other"]
    }
  },
  "required": ["reasoning", "company","role_title","scoring_inputs","muss_kriterien", "wunsch_kriterien", "gaps", "highlights", "company_one_liner", "anschreiben_hook", "contact_person", "location_type"]
}

parameters.jsCode:
const raw = $('Calculate Dimensions').first().json;
const d = raw.dimensions;

const dims = [
  { key: 'technical',    max: 40, hardMin: 8,  softMin: 16, weight: 0.35 },
  { key: 'requirements', max: 25, hardMin: 10, softMin: 15, weight: 0.20 },
  { key: 'role_fit',     max: 20, hardMin: 4,  softMin: 8,  weight: 0.25 },
  { key: 'location',     max: 10, hardMin: 0,  softMin: 3,  weight: 0.10 },
  { key: 'strategic',    max: 5,  hardMin: 0,  softMin: 0,  weight: 0.10 },
];

const PASS_THRESHOLD    = 0.62;
const CAUTION_THRESHOLD = 0.48;

const hardFails = dims.filter(d => (raw.dimensions[d.key] ?? 0) < d.hardMin);
const softFails = dims.filter(d => (raw.dimensions[d.key] ?? 0) < d.softMin && (raw.dimensions[d.key] ?? 0) >= d.hardMin);

let weighted = 0;
dims.forEach(dim => { weighted += ((raw.dimensions[dim.key] ?? 0) / dim.max) * dim.weight; });

let threshold;
if (hardFails.length >= 1) {
  threshold = 'fail';
} else if (weighted < CAUTION_THRESHOLD) {
  threshold = 'fail';
} else if (softFails.length >= 2 || weighted < PASS_THRESHOLD) {
  threshold = 'caution';
} else {
  threshold = 'pass';
}

const sum = d.technical + d.requirements + d.role_fit + d.location + d.strategic;

const validLocationTypes = ['remote','hybrid_nrw','hybrid_frankfurt','onsite_nrw','onsite_other'];

return [{
  json: {
    company:             raw.company,
    role_title:          raw.role_title,
    score:               sum,
    score_weighted:      Math.round(weighted * 100) / 100,
    threshold,
    hard_fails:          hardFails.map(d => d.key),
    soft_fails:          softFails.map(d => d.key),
    dimensions:          d,
    muss_kriterien:      raw.muss_kriterien    || [],
    wunsch_kriterien:    raw.wunsch_kriterien  || [],
    gaps:                raw.gaps              || [],
    highlights:          raw.highlights        || [],
    company_one_liner:   raw.company_one_liner || '',
    anschreiben_hook:    raw.anschreiben_hook  || '',
    contact_person:      raw.contact_person    || null,
    location_type:       validLocationTypes.includes(raw.location_type)
                           ? raw.location_type
                           : 'onsite_other',
    company_profile:     $('Start').first().json.company_profile,
    job_posting_wrapped: $('Start').first().json.job_posting_wrapped
  }
}];

const output = $('Analyzer').first().json.output;
const si = output.scoring_inputs;

// Load role_type_scores from config (key → score mapping)
const roleTypeScores = $('Start').first().json.role_type_scores;

// ── TECHNICAL (0–40) ──────────────────────────────────────
const coreMap = { 0: 0, 1: 6, 2: 12, 3: 18 };
const coreScore = si.core_skills_match_count >= 4
  ? 25
  : (coreMap[si.core_skills_match_count] ?? 0);

const secondaryMap = { 0: 0, 1: 3, 2: 6 };
const secondaryScore = si.secondary_tools_match_count >= 3
  ? 10
  : (secondaryMap[si.secondary_tools_match_count] ?? 0);

const gapsMap = {
  hard_requirement: 0,
  nice_to_have:     3,
  not_required:     5
};
const gapsScore = gapsMap[si.skill_gaps_classification] ?? 0;

const technical = coreScore + secondaryScore + gapsScore;

// ── REQUIREMENTS (0–25) ───────────────────────────────────
const pct = si.muss_kriterien_total > 0
  ? si.muss_kriterien_met / si.muss_kriterien_total
  : 0;

const requirements = pct >= 0.8 ? 25
  : pct >= 0.6 ? 18
  : pct >= 0.4 ? 12
  : 0;

// ── ROLE FIT (0–20) ───────────────────────────────────────
const formatScore = si.format_match === 'full' ? 8 : 0;

const normalizedCategory = si.role_type_category
  .toLowerCase()
  .replace(/\s+/g, '_');
const normalizedScores = Object.fromEntries(
  Object.entries(roleTypeScores).map(([k, v]) => [
    k.toLowerCase().replace(/\s+/g, '_'), v
  ])
);
const roleTypeScore = normalizedScores[normalizedCategory] ?? 0;

const role_fit = Math.min(formatScore + roleTypeScore, 20);

// ── LOCATION (0–10) ───────────────────────────────────────
const locationMap = {
  remote:               10,
  hybrid_commutable_90:  9,
  hybrid_commutable_150: 6,
  onsite_commutable_90:  5,
  onsite_commutable_150: 3,
  onsite_not_commutable: 1
};
const location = locationMap[si.location_classification] ?? 1;

// ── STRATEGIC (0–5) ───────────────────────────────────────
const strategic = Math.min(
  (si.strategic_brand        ? 2 : 0) +
  (si.strategic_ai           ? 2 : 0) +
  (si.strategic_gaps_exposure ? 1 : 0),
  5
);

// ── ASSEMBLE ──────────────────────────────────────────────
return [{
  json: {
    company:           output.company,
    role_title:        output.role_title,
    dimensions: { technical, requirements, role_fit, location, strategic },
    muss_kriterien:    output.muss_kriterien,
    wunsch_kriterien: output.wunsch_kriterien,
    gaps:              output.gaps,
    highlights:        output.highlights,
    company_one_liner: output.company_one_liner,
    anschreiben_hook:  output.anschreiben_hook,
    contact_person:    output.contact_person,
    location_type:     output.location_type,
    scoring_inputs:    si   // useful for debugging
  }
}];
